import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Card Plane ---
  const geometry = new PlaneGeometry(1.6, 1.0);
  const material = new MeshBasicNodeMaterial({
    color: new Color(config.intent?.visualSpec?.colors?.surface ?? '#0b0b10'),
    transparent: true,
  });

  // Load texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const card = new Mesh(geometry, material);
  card.position.z = -0.01; // slight offset to avoid z-fighting with text
  group.add(card);

  // --- Text Label ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = textItems.find((t) => t.role === 'headline' || t.text === 'Journal 3');
  const text = headline?.text || 'Journal 3';
  const fontSize = headline?.typography?.fontSize ?? 0.34; // headline size from design tokens

  const textMesh = ctx.fontAtlas.createText(text, {
    fontSize,
    color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
    align: 'center',
    maxWidthPx: 1.2 * 512, // loosely match card width
  });
  textMesh.position.z = 0.01;
  textMesh.scale.set(0.8, 0.8, 0.8); // fit within card
  group.add(textMesh);

  // --- Interaction Handlers ---
  const handlers = {};

  // Hover lift (rise-in)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: 0.15,
    duration: 0.5,
    ease: 'power3.out',
    overwrite: 'auto',
  });

  handlers.pointerenter = () => {
    hoverTimeline.play();
  };
  handlers.pointerleave = () => {
    hoverTimeline.reverse();
  };

  // Click: press-down + emit
  handlers.click = () => {
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
    });
    if (ctx.emit) {
      ctx.emit('hub-journal.select', { label: text });
    }
  };

  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    material.dispose();
    geometry.dispose();
    // Font atlas text mesh cleanup: if textMesh has dispose, call it
    if (textMesh.dispose) textMesh.dispose();
  };

  // Set position from config (adapter may override, but we set here)
  if (config.scenePosition) {
    group.position.set(config.scenePosition.x, config.scenePosition.y, config.scenePosition.z);
  } else {
    group.position.set(3.2, 1, 0.06);
  }
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  return group;
}
